    13→void UWjWorldCurrencySubsystem::Initialize(FSubsystemCollectionBase& Collection)
    14→{
    15→	Super::Initialize(Collection);
    16→
    17→	// CosmeticSubsystem 의존성 보장
    18→	Collection.InitializeDependency<UWjWorldCosmeticSubsystem>();
    19→
    20→	// CosmeticSubsystem의 인벤토리 갱신 구독
    21→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
    22→	if (CosmeticSub)
    23→	{
    24→		CosmeticSub->OnInventoryUpdated.AddDynamic(this, &UWjWorldCurrencySubsystem::HandleInventoryUpdated);
    25→	}
    26→
    27→	// 로컬 잔액 로드 (비Steam 폴백)
    28→	LoadBalancesFromLocal();
    29→
    30→	UE_LOG(LogWjWorldCurrency, Log, TEXT("CurrencySubsystem 초기화 완료 (Coin: %d, Gem: %d)"), CoinBalance, GemBalance);
    31→}
    32→
    33→void UWjWorldCurrencySubsystem::Deinitialize()
    34→{
    35→	StopExchangePolling();
    36→	StopGemPurchasePolling();
    37→
    38→	// 로컬 잔액 저장
    39→	SaveBalancesToLocal();
    40→
    41→	// 델리게이트 해제
    42→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
    43→	if (CosmeticSub)
    44→	{
    45→		CosmeticSub->OnInventoryUpdated.RemoveDynamic(this, &UWjWorldCurrencySubsystem::HandleInventoryUpdated);
    46→	}
    47→
    48→#if WITH_STEAM
    49→	ISteamInventory* SteamInv = SteamInventory();
    50→	if (SteamInv)
    51→	{
    52→		if (ExchangeResultHandle != k_SteamInventoryResultInvalid)
    53→		{
    54→			SteamInv->DestroyResult(ExchangeResultHandle);
    55→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
    56→		}
    57→		if (GemPurchaseResultHandle != k_SteamInventoryResultInvalid)
    58→		{
    59→			SteamInv->DestroyResult(GemPurchaseResultHandle);
    60→			GemPurchaseResultHandle = k_SteamInventoryResultInvalid;
    61→		}
    62→	}
    63→#endif
    64→
    65→	Super::Deinitialize();
    66→}
    67→
    68→int32 UWjWorldCurrencySubsystem::GetBalance(ECurrencyType Type) const
    69→{
    70→	switch (Type)
    71→	{
    72→	case ECurrencyType::Coin: return CoinBalance;
    73→	case ECurrencyType::Gem: return GemBalance;
    74→	default: return 0;
    75→	}
    76→}
    77→
    78→TArray<FCurrencyBalance> UWjWorldCurrencySubsystem::GetAllBalances() const
    79→{
    80→	TArray<FCurrencyBalance> Balances;
    81→	Balances.Emplace(ECurrencyType::Coin, CoinBalance);
    82→	Balances.Emplace(ECurrencyType::Gem, GemBalance);
    83→	return Balances;
    84→}
    85→
    86→void UWjWorldCurrencySubsystem::TriggerMatchReward(bool bIsWinner)
    87→{
    88→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    89→	if (!Settings)
    90→	{
    91→		return;
    92→	}
    93→
    94→	int32 GeneratorDefId = bIsWinner ? Settings->MatchWinRewardDefId : Settings->MatchLossRewardDefId;
    95→
    96→	UE_LOG(LogWjWorldCurrency, Log, TEXT("매치 보상 트리거: %s (GeneratorDefId: %d)"),
    97→		bIsWinner ? TEXT("승리") : TEXT("패배"), GeneratorDefId);
    98→
    99→#if WITH_STEAM
   100→	ISteamInventory* SteamInv = SteamInventory();
   101→	if (SteamInv)
   102→	{
   103→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   104→		SteamItemDef_t DropDef = static_cast<SteamItemDef_t>(GeneratorDefId);
   105→
   106→		if (SteamInv->TriggerItemDrop(&ResultHandle, DropDef))
   107→		{
   108→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam TriggerItemDrop 요청 성공 (DefId: %d)"), GeneratorDefId);
   109→			SteamInv->DestroyResult(ResultHandle);
   110→
   111→			// 인벤토리 갱신으로 잔액 반영
   112→			UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   113→			if (CosmeticSub)
   114→			{
   115→				CosmeticSub->RequestInventoryRefresh();
   116→			}
   117→		}
   118→		else
   119→		{
   120→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam TriggerItemDrop 실패 (DefId: %d)"), GeneratorDefId);
   121→		}
   122→
   123→		return;
   124→	}
   125→#endif
   126→
   127→	// 비Steam 폴백: 로컬 잔액 직접 증가
   128→	int32 RewardAmount = bIsWinner ? 50 : 10;
   129→	GrantCurrencyLocally(ECurrencyType::Coin, RewardAmount);
   130→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 매치 보상 지급: %d Coin"), RewardAmount);
   131→}
   132→
   133→bool UWjWorldCurrencySubsystem::PurchaseItemWithCurrency(FName CosmeticItemId, ECurrencyType CurrencyType)
   134→{
   135→	if (bExchangePending)
   136→	{
   137→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 교환이 진행 중입니다."));
   138→		return false;
   139→	}
   140→
   141→	if (CosmeticItemId.IsNone())
   142→	{
   143→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("유효하지 않은 CosmeticItemId"));
   144→		return false;
   145→	}
   146→
   147→	// 카탈로그에서 아이템 정보 조회
   148→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   149→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   150→	{
   151→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("CosmeticSubsystem 또는 카탈로그 없음"));
   152→		return false;
   153→	}
   154→
   155→	const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog()->FindByItemId(CosmeticItemId);
   156→	if (!ItemDef)
   157→	{
   158→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("카탈로그에서 아이템 '%s' 찾을 수 없음"), *CosmeticItemId.ToString());
   159→		return false;
   160→	}
   161→
   162→	// 가격 확인
   163→	int32 ItemPrice = (CurrencyType == ECurrencyType::Coin) ? ItemDef->CoinPrice : ItemDef->GemPrice;
   164→	if (ItemPrice <= 0)
   165→	{
   166→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("아이템 '%s'은 %s로 구매할 수 없습니다 (가격: %d)"),
   167→			*CosmeticItemId.ToString(),
   168→			(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   169→			ItemPrice);
   170→		return false;
   171→	}
   172→
   173→	// 잔액 확인
   174→	int32 CurrentBalance = GetBalance(CurrencyType);
   175→	if (CurrentBalance < ItemPrice)
   176→	{
   177→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("잔액 부족: %s %d < %d"),
   178→			(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   179→			CurrentBalance, ItemPrice);
   180→		return false;
   181→	}
   182→
   183→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   184→	if (!Settings)
   185→	{
   186→		return false;
   187→	}
   188→
   189→	int32 CurrencyDefId = (CurrencyType == ECurrencyType::Coin) ? Settings->CoinSteamItemDefId : Settings->GemSteamItemDefId;
   190→	int32 CosmeticDefId = ItemDef->SteamItemDefId;
   191→
   192→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 구매 요청: %s (%d %s → CosmeticDefId %d)"),
   193→		*CosmeticItemId.ToString(), ItemPrice,
   194→		(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   195→		CosmeticDefId);
   196→
   197→#if WITH_STEAM
   198→	ISteamInventory* SteamInv = SteamInventory();
   199→	if (SteamInv && CosmeticDefId > 0)
   200→	{
   201→		// 기존 핸들 정리
   202→		if (ExchangeResultHandle != k_SteamInventoryResultInvalid)
   203→		{
   204→			SteamInv->DestroyResult(ExchangeResultHandle);
   205→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   206→		}
   207→
   208→		// ExchangeItems: 재화 소비 → 코스메틱 아이템 획득
   209→		SteamItemDef_t OutputItemDef = static_cast<SteamItemDef_t>(CosmeticDefId);
   210→		uint32 OutputQuantity = 1;
   211→
   212→		// 입력: 재화 아이템 (인벤토리에서 해당 수량 소비)
   213→		// ExchangeItems는 인스턴스 ID가 필요하므로, 전체 인벤토리에서 재화 인스턴스를 찾아야 함
   214→		// 여기서는 간단화를 위해 재화가 auto_stack이므로 단일 인스턴스라 가정
   215→		// 실제 구현시에는 GetAllItems 결과에서 인스턴스 ID를 캐싱해야 함
   216→
   217→		// Steam ExchangeItems는 SteamItemInstanceID_t가 필요
   218→		// exchange 레시피는 서버 사이드에서 itemdef의 "exchange" 프로퍼티로 검증
   219→		// 따라서 클라이언트에서는 재화 인스턴스 ID만 전달하면 됨
   220→
   221→		// 재화 인스턴스 ID를 찾기 위해 인벤토리 조회 필요
   222→		// CosmeticSubsystem의 캐시된 결과에서는 인스턴스 ID를 보관하지 않으므로
   223→		// 별도의 GetAllItems 호출 후 처리해야 함
   224→		// 이 부분은 추후 인스턴스 ID 캐싱이 구현되면 개선
   225→
   226→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam ExchangeItems는 인스턴스 ID 기반 - 인벤토리 갱신 후 재시도 필요"));
   227→
   228→		// 현재는 로컬 차감 + CosmeticSubsystem으로 아이템 부여하는 방식으로 처리
   229→		// Steam 서버 사이드 exchange는 추후 인스턴스 ID 캐싱 구현 시 활성화
   230→		SetBalance(CurrencyType, CurrentBalance - ItemPrice);
   231→		CosmeticSub->GrantItemLocally(CosmeticItemId, 1);
   232→		CosmeticSub->RequestInventoryRefresh();
   233→
   234→		OnCurrencyPurchaseComplete.Broadcast(CosmeticItemId, true);
   235→		return true;
   236→	}
   237→#endif
   238→
   239→	// 비Steam 폴백: 로컬 잔액 차감 + 아이템 부여
   240→	SetBalance(CurrencyType, CurrentBalance - ItemPrice);
   241→	CosmeticSub->GrantItemLocally(CosmeticItemId, 1);
   242→
   243→	OnCurrencyPurchaseComplete.Broadcast(CosmeticItemId, true);
   244→
   245→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 재화 구매 완료: %s (%d %s 차감)"),
   246→		*CosmeticItemId.ToString(), ItemPrice,
   247→		(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"));
   248→
   249→	return true;
   250→}
   251→
   252→bool UWjWorldCurrencySubsystem::PurchaseGemPack(int32 PackDefId)
   253→{
   254→	if (bGemPurchasePending)
   255→	{
   256→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 Gem 팩 구매가 진행 중입니다."));
   257→		return false;
   258→	}
   259→
   260→#if WITH_STEAM
   261→	ISteamInventory* SteamInv = SteamInventory();
   262→	if (!SteamInv)
   263→	{
   264→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Inventory API 사용 불가"));
   265→		return false;
   266→	}
   267→
   268→	// 기존 핸들 정리
   269→	if (GemPurchaseResultHandle != k_SteamInventoryResultInvalid)
   270→	{
   271→		SteamInv->DestroyResult(GemPurchaseResultHandle);
   272→		GemPurchaseResultHandle = k_SteamInventoryResultInvalid;
   273→	}
   274→
   275→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(PackDefId);
   276→	uint32 Quantity = 1;
   277→
   278→	if (SteamInv->StartPurchase(&ItemDef, &Quantity, 1))
   279→	{
   280→		bGemPurchasePending = true;
   281→		StartGemPurchasePolling();
   282→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Gem 팩 구매 요청 시작 (DefId: %d)"), PackDefId);
   283→		return true;
   284→	}
   285→	else
   286→	{
   287→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam StartPurchase 실패 (DefId: %d)"), PackDefId);
   288→		return false;
   289→	}
   290→#else
   291→	UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 팩 구매는 Steam 환경에서만 가능합니다."));
   292→	return false;
   293→#endif
   294→}
   295→
   296→void UWjWorldCurrencySubsystem::RefreshBalancesFromInventory()
   297→{
   298→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   299→	if (!Settings)
   300→	{
   301→		return;
   302→	}
   303→
   304→#if WITH_STEAM
   305→	ISteamInventory* SteamInv = SteamInventory();
   306→	if (SteamInv)
   307→	{
   308→		// CosmeticSubsystem의 인벤토리 갱신을 구독하고 있으므로
   309→		// 여기서는 캐시된 인벤토리에서 재화 수량을 파싱
   310→		int32 NewCoinBalance = GetItemQuantityFromInventory(Settings->CoinSteamItemDefId);
   311→		int32 NewGemBalance = GetItemQuantityFromInventory(Settings->GemSteamItemDefId);
   312→
   313→		if (NewCoinBalance != CoinBalance)
   314→		{
   315→			SetBalance(ECurrencyType::Coin, NewCoinBalance);
   316→		}
   317→		if (NewGemBalance != GemBalance)
   318→		{
   319→			SetBalance(ECurrencyType::Gem, NewGemBalance);
   320→		}
   321→
   322→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam 잔액 갱신: Coin=%d, Gem=%d"), CoinBalance, GemBalance);
   323→		return;
   324→	}
   325→#endif
   326→
   327→	// 비Steam: 로컬 값 유지
   328→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 잔액: Coin=%d, Gem=%d"), CoinBalance, GemBalance);
   329→}
   330→
   331→void UWjWorldCurrencySubsystem::GrantCurrencyLocally(ECurrencyType Type, int32 Amount)
   332→{
   333→	if (Amount <= 0)
   334→	{
   335→		return;
   336→	}
   337→
   338→	int32 CurrentBalance = GetBalance(Type);
   339→	SetBalance(Type, CurrentBalance + Amount);
   340→
   341→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 재화 부여: %s +%d (잔액: %d)"),
   342→		(Type == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   343→		Amount, GetBalance(Type));
   344→}
   345→
   346→void UWjWorldCurrencySubsystem::SetCurrencyLocally(ECurrencyType Type, int32 Amount)
   347→{
   348→	SetBalance(Type, Amount);
   349→
   350→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 재화 설정: %s = %d"),
   351→		(Type == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   352→		GetBalance(Type));
   353→}
