   357→	UE_LOG(LogWjWorldCurrency, Log, TEXT("========== 재화 잔액 =========="));
   358→	UE_LOG(LogWjWorldCurrency, Log, TEXT("  Coin: %d"), CoinBalance);
   359→	UE_LOG(LogWjWorldCurrency, Log, TEXT("  Gem:  %d"), GemBalance);
