   367→
   368→int32 UWjWorldCurrencySubsystem::GetItemQuantityFromInventory(int32 SteamItemDefId) const
   369→{
   370→	// CosmeticSubsystem의 캐시된 인벤토리에서 해당 DefId의 수량을 찾음
   371→	// 재화 아이템은 CosmeticCatalog에 등록되어 있지 않으므로
   372→	// CosmeticSubsystem의 파싱에서 "알 수 없는 SteamItemDefId"로 스킵됨
   373→	// 따라서 별도의 Steam Inventory 조회가 필요
   374→
   375→	// 현재는 CosmeticSubsystem의 인벤토리 갱신 시점에 호출되므로
   376→	// 직접 Steam API를 호출하여 확인
   377→#if WITH_STEAM
   378→	ISteamInventory* SteamInv = SteamInventory();
   379→	if (!SteamInv)
   380→	{
   381→		return 0;
   382→	}
   383→
   384→	SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   385→	if (!SteamInv->GetAllItems(&ResultHandle))
   386→	{
   387→		return 0;
   388→	}
   389→
   390→	// 결과 대기 (동기적 폴링 - 이미 캐시된 경우 즉시 반환)
   391→	// 참고: GetAllItems는 이전에 성공한 결과가 캐시되어 있으면 즉시 반환됨
   392→	int32 TotalQuantity = 0;
   393→
   394→	EResult Status = SteamInv->GetResultStatus(ResultHandle);
   395→	if (Status == k_EResultOK)
   396→	{
   397→		uint32 ItemCount = 0;
   398→		if (SteamInv->GetResultItems(ResultHandle, nullptr, &ItemCount) && ItemCount > 0)
   399→		{
   400→			TArray<SteamItemDetails_t> ItemDetails;
   401→			ItemDetails.SetNum(ItemCount);
   402→
   403→			if (SteamInv->GetResultItems(ResultHandle, ItemDetails.GetData(), &ItemCount))
   404→			{
   405→				for (uint32 i = 0; i < ItemCount; ++i)
   406→				{
   407→					if (ItemDetails[i].m_iDefinition == SteamItemDefId && ItemDetails[i].m_unQuantity > 0)
   408→					{
   409→						TotalQuantity += ItemDetails[i].m_unQuantity;
   410→					}
   411→				}
   412→			}
   413→		}
   414→	}
   415→
   416→	SteamInv->DestroyResult(ResultHandle);
   417→	return TotalQuantity;
   418→#else
   419→	return 0;
   420→#endif
   421→}
   422→
   423→void UWjWorldCurrencySubsystem::PollExchangeResult()
   424→{
   425→#if WITH_STEAM
   426→	if (!bExchangePending || ExchangeResultHandle == k_SteamInventoryResultInvalid)
   427→	{
   428→		StopExchangePolling();
   429→		return;
   430→	}
   431→
   432→	ISteamInventory* SteamInv = SteamInventory();
   433→	if (!SteamInv)
   434→	{
   435→		StopExchangePolling();
   436→		bExchangePending = false;
   437→		OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   438→		PendingExchangeItemId = NAME_None;
   439→		return;
   440→	}
   441→
   442→	EResult Status = SteamInv->GetResultStatus(ExchangeResultHandle);
   443→	if (Status == k_EResultPending)
   444→	{
   445→		return;
   446→	}
   447→
   448→	bool bSuccess = (Status == k_EResultOK);
   449→	if (bSuccess)
   450→	{
   451→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Exchange 성공: %s"), *PendingExchangeItemId.ToString());
   452→
   453→		// 인벤토리 갱신
   454→		UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   455→		if (CosmeticSub)
   456→		{
   457→			CosmeticSub->RequestInventoryRefresh();
   458→		}
   459→	}
   460→	else
   461→	{
   462→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Exchange 실패: %s (Status: %d)"),
   463→			*PendingExchangeItemId.ToString(), static_cast<int32>(Status));
   464→	}
   465→
   466→	SteamInv->DestroyResult(ExchangeResultHandle);
   467→	ExchangeResultHandle = k_SteamInventoryResultInvalid;
   468→
   469→	bExchangePending = false;
   470→	OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   471→	PendingExchangeItemId = NAME_None;
   472→
   473→	StopExchangePolling();
   474→#else
   475→	StopExchangePolling();
   476→#endif
   477→}
   478→
   479→void UWjWorldCurrencySubsystem::StartExchangePolling()
   480→{
   481→	UWorld* World = GetWorld();
   482→	if (!World)
   483→	{
   484→		return;
   485→	}
   486→
   487→	World->GetTimerManager().SetTimer(
   488→		ExchangePollTimerHandle,
   489→		this,
   490→		&UWjWorldCurrencySubsystem::PollExchangeResult,
   491→		0.5f,
   492→		true
   493→	);
   494→}
   495→
   496→void UWjWorldCurrencySubsystem::StopExchangePolling()
   497→{
   498→	UWorld* World = GetWorld();
   499→	if (World)
   500→	{
   501→		World->GetTimerManager().ClearTimer(ExchangePollTimerHandle);
   502→	}
   503→}
   504→
   505→void UWjWorldCurrencySubsystem::PollGemPurchaseResult()
   506→{
   507→#if WITH_STEAM
   508→	if (!bGemPurchasePending)
   509→	{
   510→		StopGemPurchasePolling();
   511→		return;
   512→	}
   513→
   514→	// Gem 팩 구매는 Steam 오버레이를 통해 처리되므로
   515→	// 인벤토리 변경을 감지하여 완료 판단
   516→	// CosmeticSubsystem의 OnInventoryUpdated → HandleInventoryUpdated → RefreshBalancesFromInventory
   517→	// 에서 Gem 잔액 변경이 감지되면 구매 완료로 판단
   518→
   519→	// 간단한 타임아웃 처리 (300초)
   520→	UWorld* World = GetWorld();
   521→	if (World)
   522→	{
   523→		if (GemPurchaseStartTime == 0.0f)
   524→		{
   525→			GemPurchaseStartTime = World->GetTimeSeconds();
   526→		}
   527→
   528→		float ElapsedTime = World->GetTimeSeconds() - GemPurchaseStartTime;
   529→		if (ElapsedTime > 300.0f)
   530→		{
   531→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 팩 구매 타임아웃"));
   532→			bGemPurchasePending = false;
   533→			GemPurchaseStartTime = 0.0f;
   534→			StopGemPurchasePolling();
   535→		}
   536→	}
   537→#else
   538→	StopGemPurchasePolling();
   539→#endif
   540→}
   541→
   542→void UWjWorldCurrencySubsystem::StartGemPurchasePolling()
   543→{
   544→	UWorld* World = GetWorld();
   545→	if (!World)
   546→	{
   547→		return;
   548→	}
   549→
   550→	World->GetTimerManager().SetTimer(
   551→		GemPurchasePollTimerHandle,
   552→		this,
   553→		&UWjWorldCurrencySubsystem::PollGemPurchaseResult,
   554→		1.0f,
   555→		true
   556→	);
   557→}
   558→
   559→void UWjWorldCurrencySubsystem::StopGemPurchasePolling()
   560→{
   561→	UWorld* World = GetWorld();
   562→	if (World)
   563→	{
   564→		World->GetTimerManager().ClearTimer(GemPurchasePollTimerHandle);
   565→	}
   566→}
