    89→void UWjWorldCurrencySubsystem::TriggerMatchReward(bool bIsWinner)
    90→{
    91→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    92→	if (!Settings)
    93→	{
    94→		return;
    95→	}
    96→
    97→	int32 GeneratorDefId = bIsWinner ? Settings->MatchWinRewardDefId : Settings->MatchLossRewardDefId;
    98→
    99→	UE_LOG(LogWjWorldCurrency, Log, TEXT("매치 보상 트리거: %s (GeneratorDefId: %d)"),
   100→		bIsWinner ? TEXT("승리") : TEXT("패배"), GeneratorDefId);
   101→
   102→#if WITH_STEAM
   103→	ISteamInventory* SteamInv = SteamInventory();
   104→	if (SteamInv)
   105→	{
   106→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   107→		SteamItemDef_t DropDef = static_cast<SteamItemDef_t>(GeneratorDefId);
   108→
   109→		if (SteamInv->TriggerItemDrop(&ResultHandle, DropDef))
   110→		{
   111→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam TriggerItemDrop 요청 성공 (DefId: %d)"), GeneratorDefId);
   112→			SteamInv->DestroyResult(ResultHandle);
   113→
   114→			// 인벤토리 갱신으로 잔액 반영
   115→			UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   116→			if (CosmeticSub)
   117→			{
   118→				CosmeticSub->RequestInventoryRefresh();
   119→			}
   120→		}
   121→		else
   122→		{
   123→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam TriggerItemDrop 실패 (DefId: %d)"), GeneratorDefId);
   124→		}
   125→
   126→		return;
   127→	}
   128→#endif
   129→
   130→	// 비Steam 폴백: 로컬 잔액 직접 증가
   131→	int32 RewardAmount = bIsWinner ? 50 : 10;
   132→	GrantCurrencyLocally(ECurrencyType::Coin, RewardAmount);
   133→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 매치 보상 지급: %d Coin"), RewardAmount);
   134→}
   135→
   136→bool UWjWorldCurrencySubsystem::PurchaseItemWithCurrency(FName CosmeticItemId, ECurrencyType CurrencyType)
   137→{
   138→	if (bExchangePending)
   139→	{
   140→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 교환이 진행 중입니다."));
   141→		return false;
   142→	}
   143→
   144→	if (CosmeticItemId.IsNone())
   145→	{
   146→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("유효하지 않은 CosmeticItemId"));
   147→		return false;
   148→	}
   149→
   150→	// 카탈로그에서 아이템 정보 조회
   151→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   152→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   153→	{
   154→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("CosmeticSubsystem 또는 카탈로그 없음"));
   155→		return false;
   156→	}
   157→
   158→	const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog()->FindByItemId(CosmeticItemId);
   159→	if (!ItemDef)
   160→	{
   161→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("카탈로그에서 아이템 '%s' 찾을 수 없음"), *CosmeticItemId.ToString());
   162→		return false;
   163→	}
   164→
   165→	// 가격 확인
   166→	int32 ItemPrice = (CurrencyType == ECurrencyType::Coin) ? ItemDef->CoinPrice : ItemDef->GemPrice;
   167→	if (ItemPrice <= 0)
   168→	{
   169→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("아이템 '%s'은 %s로 구매할 수 없습니다 (가격: %d)"),
   170→			*CosmeticItemId.ToString(),
   171→			(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   172→			ItemPrice);
   173→		return false;
   174→	}
   175→
   176→	// 잔액 확인
   177→	int32 CurrentBalance = GetBalance(CurrencyType);
   178→	if (CurrentBalance < ItemPrice)
   179→	{
   180→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("잔액 부족: %s %d < %d"),
   181→			(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   182→			CurrentBalance, ItemPrice);
   183→		return false;
   184→	}
   185→
   186→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   187→	if (!Settings)
   188→	{
   189→		return false;
   190→	}
   191→
   192→	int32 CurrencyDefId = (CurrencyType == ECurrencyType::Coin) ? Settings->CoinSteamItemDefId : Settings->GemSteamItemDefId;
   193→	int32 CosmeticDefId = ItemDef->SteamItemDefId;
   194→
   195→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 구매 요청: %s (%d %s → CosmeticDefId %d)"),
   196→		*CosmeticItemId.ToString(), ItemPrice,
   197→		(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   198→		CosmeticDefId);
   199→
   200→#if WITH_STEAM
   201→	ISteamInventory* SteamInv = SteamInventory();
   202→	if (SteamInv && CosmeticDefId > 0)
   203→	{
   204→		// 캐시된 재화 인스턴스 ID 조회
   205→		SteamItemInstanceID_t CurrencyInstanceId = (CurrencyType == ECurrencyType::Coin)
   206→			? CachedCoinInstanceId
   207→			: CachedGemInstanceId;
   208→
   209→		if (CurrencyInstanceId == k_SteamItemInstanceIDInvalid)
   210→		{
   211→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("재화 인스턴스 ID가 캐싱되지 않음 — 인벤토리 갱신 필요"));
   212→			return false;
   213→		}
   214→
   215→		// 기존 핸들 정리
   216→		if (ExchangeResultHandle != k_SteamInventoryResultInvalid)
   217→		{
   218→			SteamInv->DestroyResult(ExchangeResultHandle);
   219→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   220→		}
   221→
   222→		// ExchangeItems: 재화 소비 → 코스메틱 아이템 획득
   223→		SteamItemDef_t OutputItemDef = static_cast<SteamItemDef_t>(CosmeticDefId);
   224→		uint32 OutputQuantity = 1;
   225→
   226→		uint32 InputQuantity = static_cast<uint32>(ItemPrice);
   227→
   228→		bool bExchangeResult = SteamInv->ExchangeItems(
   229→			&ExchangeResultHandle,
   230→			&OutputItemDef, &OutputQuantity, 1,       // 출력: 코스메틱 아이템 1개
   231→			&CurrencyInstanceId, &InputQuantity, 1     // 입력: 재화 인스턴스 × 가격
   232→		);
   233→
   234→		if (bExchangeResult)
   235→		{
   236→			bExchangePending = true;
   237→			PendingExchangeItemId = CosmeticItemId;
   238→			StartExchangePolling();
   239→
   240→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam ExchangeItems 요청 성공: %s (CurrencyInstanceId=%llu, Price=%d)"),
   241→				*CosmeticItemId.ToString(), CurrencyInstanceId, ItemPrice);
   242→			return true;
   243→		}
   244→		else
   245→		{
   246→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam ExchangeItems 호출 실패: %s"), *CosmeticItemId.ToString());
   247→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   248→			return false;
   249→		}
   250→	}
   251→#endif
   252→
   253→	// 비Steam 폴백: 로컬 잔액 차감 + 아이템 부여
   254→	SetBalance(CurrencyType, CurrentBalance - ItemPrice);
   255→	CosmeticSub->GrantItemLocally(CosmeticItemId, 1);
   256→
   257→	OnCurrencyPurchaseComplete.Broadcast(CosmeticItemId, true);
   258→
   259→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 재화 구매 완료: %s (%d %s 차감)"),
   260→		*CosmeticItemId.ToString(), ItemPrice,
   261→		(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"));
   262→
   263→	return true;
   264→}
   265→
   266→bool UWjWorldCurrencySubsystem::PurchaseGemPack(int32 PackDefId)
   267→{
   268→	if (bGemPurchasePending)
   269→	{
   270→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 Gem 팩 구매가 진행 중입니다."));
   271→		return false;
   272→	}
   273→
   274→#if WITH_STEAM
   275→	ISteamInventory* SteamInv = SteamInventory();
   276→	if (!SteamInv)
   277→	{
   278→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Inventory API 사용 불가"));
   279→		return false;
   280→	}
   281→
   282→	// 기존 핸들 정리
   283→	if (GemPurchaseResultHandle != k_SteamInventoryResultInvalid)
   284→	{
   285→		SteamInv->DestroyResult(GemPurchaseResultHandle);
   286→		GemPurchaseResultHandle = k_SteamInventoryResultInvalid;
   287→	}
   288→
   289→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(PackDefId);
   290→	uint32 Quantity = 1;
   291→
   292→	if (SteamInv->StartPurchase(&ItemDef, &Quantity, 1))
   293→	{
   294→		bGemPurchasePending = true;
   295→		StartGemPurchasePolling();
   296→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Gem 팩 구매 요청 시작 (DefId: %d)"), PackDefId);
   297→		return true;
   298→	}
   299→	else
   300→	{
   301→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam StartPurchase 실패 (DefId: %d)"), PackDefId);
   302→		return false;
   303→	}
   304→#else
   305→	UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 팩 구매는 Steam 환경에서만 가능합니다."));
   306→	return false;
   307→#endif
   308→}
   309→
   310→void UWjWorldCurrencySubsystem::RefreshBalancesFromInventory()
   311→{
   312→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   313→	if (!Settings)
   314→	{
   315→		return;
   316→	}
   317→
   318→#if WITH_STEAM
   319→	ISteamInventory* SteamInv = SteamInventory();
   320→	if (SteamInv)
   321→	{
   322→		// 단일 GetAllItems 호출로 잔액 + 인스턴스 ID 동시 캐싱
   323→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   324→		if (!SteamInv->GetAllItems(&ResultHandle))
   325→		{
   326→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam GetAllItems 실패"));
   327→			return;
   328→		}
   329→
   330→		int32 NewCoinBalance = 0;
   331→		int32 NewGemBalance = 0;
   332→		SteamItemInstanceID_t NewCoinInstanceId = k_SteamItemInstanceIDInvalid;
   333→		SteamItemInstanceID_t NewGemInstanceId = k_SteamItemInstanceIDInvalid;
   334→
   335→		EResult Status = SteamInv->GetResultStatus(ResultHandle);
   336→		if (Status == k_EResultOK)
   337→		{
   338→			uint32 ItemCount = 0;
   339→			if (SteamInv->GetResultItems(ResultHandle, nullptr, &ItemCount) && ItemCount > 0)
   340→			{
   341→				TArray<SteamItemDetails_t> ItemDetails;
   342→				ItemDetails.SetNum(ItemCount);
   343→
   344→				if (SteamInv->GetResultItems(ResultHandle, ItemDetails.GetData(), &ItemCount))
   345→				{
   346→					for (uint32 i = 0; i < ItemCount; ++i)
   347→					{
   348→						const SteamItemDetails_t& Detail = ItemDetails[i];
   349→						if (Detail.m_unQuantity == 0)
   350→						{
   351→							continue;
   352→						}
   353→
   354→						if (Detail.m_iDefinition == Settings->CoinSteamItemDefId)
   355→						{
   356→							NewCoinBalance += Detail.m_unQuantity;
   357→							NewCoinInstanceId = Detail.m_itemId;
   358→						}
   359→						else if (Detail.m_iDefinition == Settings->GemSteamItemDefId)
   360→						{
   361→							NewGemBalance += Detail.m_unQuantity;
   362→							NewGemInstanceId = Detail.m_itemId;
   363→						}
   364→					}
   365→				}
   366→			}
   367→		}
   368→
   369→		SteamInv->DestroyResult(ResultHandle);
   370→
   371→		// 인스턴스 ID 캐시 갱신
   372→		CachedCoinInstanceId = NewCoinInstanceId;
   373→		CachedGemInstanceId = NewGemInstanceId;
   374→
   375→		// 잔액 갱신
   376→		if (NewCoinBalance != CoinBalance)
   377→		{
   378→			SetBalance(ECurrencyType::Coin, NewCoinBalance);
   379→		}
   380→		if (NewGemBalance != GemBalance)
   381→		{
   382→			SetBalance(ECurrencyType::Gem, NewGemBalance);
   383→		}
   384→
   385→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam 잔액 갱신: Coin=%d (InstanceId=%llu), Gem=%d (InstanceId=%llu)"),
   386→			CoinBalance, CachedCoinInstanceId, GemBalance, CachedGemInstanceId);
   387→		return;
   388→	}
   389→#endif
   390→
   391→	// 비Steam: 로컬 값 유지
   392→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 잔액: Coin=%d, Gem=%d"), CoinBalance, GemBalance);
   393→}
   394→
   395→void UWjWorldCurrencySubsystem::GrantCurrencyLocally(ECurrencyType Type, int32 Amount)
   396→{
   397→	if (Amount <= 0)
   398→	{
   399→		return;
   400→	}
   401→
   402→	int32 CurrentBalance = GetBalance(Type);
   403→	SetBalance(Type, CurrentBalance + Amount);
   404→
   405→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 재화 부여: %s +%d (잔액: %d)"),
   406→		(Type == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   407→		Amount, GetBalance(Type));
   408→}
   409→
   410→void UWjWorldCurrencySubsystem::SetCurrencyLocally(ECurrencyType Type, int32 Amount)
   411→{
   412→	SetBalance(Type, Amount);
   413→
   414→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 재화 설정: %s = %d"),
   415→		(Type == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   416→		GetBalance(Type));
   417→}
