   421→	UE_LOG(LogWjWorldCurrency, Log, TEXT("========== 재화 잔액 =========="));
   422→	UE_LOG(LogWjWorldCurrency, Log, TEXT("  Coin: %d"), CoinBalance);
   423→	UE_LOG(LogWjWorldCurrency, Log, TEXT("  Gem:  %d"), GemBalance);
   424→	UE_LOG(LogWjWorldCurrency, Log, TEXT("================================"));
