   426→
   427→void UWjWorldCurrencySubsystem::HandleInventoryUpdated()
   428→{
   429→	RefreshBalancesFromInventory();
   430→}
   431→
   432→void UWjWorldCurrencySubsystem::PollExchangeResult()
   433→{
   434→#if WITH_STEAM
   435→	if (!bExchangePending || ExchangeResultHandle == k_SteamInventoryResultInvalid)
   436→	{
   437→		StopExchangePolling();
   438→		return;
   439→	}
   440→
   441→	ISteamInventory* SteamInv = SteamInventory();
   442→	if (!SteamInv)
   443→	{
   444→		StopExchangePolling();
   445→		bExchangePending = false;
   446→		OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   447→		PendingExchangeItemId = NAME_None;
   448→		return;
   449→	}
   450→
   451→	EResult Status = SteamInv->GetResultStatus(ExchangeResultHandle);
   452→	if (Status == k_EResultPending)
   453→	{
   454→		return;
   455→	}
   456→
   457→	bool bSuccess = (Status == k_EResultOK);
   458→	if (bSuccess)
   459→	{
   460→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Exchange 성공: %s"), *PendingExchangeItemId.ToString());
   461→
   462→		// 인벤토리 갱신
   463→		UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   464→		if (CosmeticSub)
   465→		{
   466→			CosmeticSub->RequestInventoryRefresh();
   467→		}
   468→	}
   469→	else
   470→	{
   471→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Exchange 실패: %s (Status: %d)"),
   472→			*PendingExchangeItemId.ToString(), static_cast<int32>(Status));
   473→	}
   474→
   475→	SteamInv->DestroyResult(ExchangeResultHandle);
   476→	ExchangeResultHandle = k_SteamInventoryResultInvalid;
   477→
   478→	bExchangePending = false;
   479→	OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   480→	PendingExchangeItemId = NAME_None;
   481→
   482→	StopExchangePolling();
   483→#else
   484→	StopExchangePolling();
   485→#endif
   486→}
   487→
   488→void UWjWorldCurrencySubsystem::StartExchangePolling()
   489→{
   490→	UWorld* World = GetWorld();
   491→	if (!World)
   492→	{
   493→		return;
   494→	}
   495→
   496→	World->GetTimerManager().SetTimer(
   497→		ExchangePollTimerHandle,
   498→		this,
   499→		&UWjWorldCurrencySubsystem::PollExchangeResult,
   500→		0.5f,
   501→		true
   502→	);
   503→}
   504→
   505→void UWjWorldCurrencySubsystem::StopExchangePolling()
   506→{
   507→	UWorld* World = GetWorld();
   508→	if (World)
   509→	{
   510→		World->GetTimerManager().ClearTimer(ExchangePollTimerHandle);
   511→	}
   512→}
   513→
   514→void UWjWorldCurrencySubsystem::PollGemPurchaseResult()
   515→{
   516→#if WITH_STEAM
   517→	if (!bGemPurchasePending)
   518→	{
   519→		StopGemPurchasePolling();
   520→		return;
   521→	}
   522→
   523→	// Gem 팩 구매는 Steam 오버레이를 통해 처리되므로
   524→	// 인벤토리 변경을 감지하여 완료 판단
   525→	// CosmeticSubsystem의 OnInventoryUpdated → HandleInventoryUpdated → RefreshBalancesFromInventory
   526→	// 에서 Gem 잔액 변경이 감지되면 구매 완료로 판단
   527→
   528→	// 간단한 타임아웃 처리 (300초)
   529→	UWorld* World = GetWorld();
   530→	if (World)
   531→	{
   532→		if (GemPurchaseStartTime == 0.0f)
   533→		{
   534→			GemPurchaseStartTime = World->GetTimeSeconds();
   535→		}
   536→
   537→		float ElapsedTime = World->GetTimeSeconds() - GemPurchaseStartTime;
   538→		if (ElapsedTime > 300.0f)
   539→		{
   540→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 팩 구매 타임아웃"));
   541→			bGemPurchasePending = false;
   542→			GemPurchaseStartTime = 0.0f;
   543→			StopGemPurchasePolling();
   544→		}
   545→	}
   546→#else
   547→	StopGemPurchasePolling();
   548→#endif
   549→}
   550→
   551→void UWjWorldCurrencySubsystem::StartGemPurchasePolling()
   552→{
   553→	UWorld* World = GetWorld();
   554→	if (!World)
   555→	{
   556→		return;
   557→	}
   558→
   559→	World->GetTimerManager().SetTimer(
   560→		GemPurchasePollTimerHandle,
   561→		this,
   562→		&UWjWorldCurrencySubsystem::PollGemPurchaseResult,
   563→		1.0f,
   564→		true
   565→	);
   566→}
   567→
   568→void UWjWorldCurrencySubsystem::StopGemPurchasePolling()
   569→{
   570→	UWorld* World = GetWorld();
   571→	if (World)
   572→	{
   573→		World->GetTimerManager().ClearTimer(GemPurchasePollTimerHandle);
   574→	}
   575→}
