   577→void UWjWorldCurrencySubsystem::SaveBalancesToLocal()
   578→{
   579→	FString ConfigFilePath = FPaths::GeneratedConfigDir() + TEXT("CurrencyBalance.ini");
   580→
   581→	GConfig->SetInt(*CurrencyConfigSection, TEXT("CoinBalance"), CoinBalance, ConfigFilePath);
   582→	GConfig->SetInt(*CurrencyConfigSection, TEXT("GemBalance"), GemBalance, ConfigFilePath);
   583→
   584→	GConfig->Flush(false, ConfigFilePath);
   585→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 잔액 로컬 저장 완료"));
   586→}
   587→
   588→void UWjWorldCurrencySubsystem::LoadBalancesFromLocal()
   589→{
   590→	FString ConfigFilePath = FPaths::GeneratedConfigDir() + TEXT("CurrencyBalance.ini");
   591→
   592→	int32 LoadedCoin = 0;
   593→	int32 LoadedGem = 0;
   594→
   595→	GConfig->GetInt(*CurrencyConfigSection, TEXT("CoinBalance"), LoadedCoin, ConfigFilePath);
   596→	GConfig->GetInt(*CurrencyConfigSection, TEXT("GemBalance"), LoadedGem, ConfigFilePath);
   597→
   598→	CoinBalance = FMath::Max(0, LoadedCoin);
   599→	GemBalance = FMath::Max(0, LoadedGem);
   600→
   601→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 잔액 로컬 로드 완료 (Coin: %d, Gem: %d)"), CoinBalance, GemBalance);
   602→}
   603→
   604→void UWjWorldCurrencySubsystem::SetBalance(ECurrencyType Type, int32 NewAmount)
   605→{
   606→	NewAmount = FMath::Max(0, NewAmount);
   607→
   608→	switch (Type)
   609→	{
   610→	case ECurrencyType::Coin:
   611→		if (CoinBalance != NewAmount)
   612→		{
   613→			CoinBalance = NewAmount;
   614→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Coin, CoinBalance);
   615→		}
   616→		break;
   617→	case ECurrencyType::Gem:
   618→		if (GemBalance != NewAmount)
   619→		{
   620→			GemBalance = NewAmount;
   621→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Gem, GemBalance);
   622→		}
   623→		break;
   624→	}
   625→}
