   310→void UWjWorldCurrencySubsystem::RefreshBalancesFromInventory()
   311→{
   312→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   313→	if (!Settings)
   314→	{
   315→		return;
   316→	}
   317→
   318→#if WITH_STEAM
   319→	ISteamInventory* SteamInv = SteamInventory();
   320→	if (SteamInv)
   321→	{
   322→		// 단일 GetAllItems 호출로 잔액 + 인스턴스 ID 동시 캐싱
   323→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   324→		if (!SteamInv->GetAllItems(&ResultHandle))
   325→		{
   326→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam GetAllItems 실패"));
   327→			return;
   328→		}
   329→
   330→		int32 NewCoinBalance = 0;
   331→		int32 NewGemBalance = 0;
   332→		SteamItemInstanceID_t NewCoinInstanceId = k_SteamItemInstanceIDInvalid;
   333→		SteamItemInstanceID_t NewGemInstanceId = k_SteamItemInstanceIDInvalid;
   334→
   335→		EResult Status = SteamInv->GetResultStatus(ResultHandle);
   336→		if (Status == k_EResultOK)
   337→		{
   338→			uint32 ItemCount = 0;
   339→			if (SteamInv->GetResultItems(ResultHandle, nullptr, &ItemCount) && ItemCount > 0)
   340→			{
   341→				TArray<SteamItemDetails_t> ItemDetails;
   342→				ItemDetails.SetNum(ItemCount);
   343→
   344→				if (SteamInv->GetResultItems(ResultHandle, ItemDetails.GetData(), &ItemCount))
   345→				{
   346→					for (uint32 i = 0; i < ItemCount; ++i)
   347→					{
   348→						const SteamItemDetails_t& Detail = ItemDetails[i];
   349→						if (Detail.m_unQuantity == 0)
   350→						{
   351→							continue;
   352→						}
   353→
   354→						if (Detail.m_iDefinition == Settings->CoinSteamItemDefId)
   355→						{
   356→							NewCoinBalance += Detail.m_unQuantity;
   357→							NewCoinInstanceId = Detail.m_itemId;
   358→						}
   359→						else if (Detail.m_iDefinition == Settings->GemSteamItemDefId)
   360→						{
   361→							NewGemBalance += Detail.m_unQuantity;
   362→							NewGemInstanceId = Detail.m_itemId;
   363→						}
   364→					}
   365→				}
   366→			}
   367→		}
   368→
   369→		SteamInv->DestroyResult(ResultHandle);
   370→
   371→		// 인스턴스 ID 캐시 갱신
   372→		CachedCoinInstanceId = NewCoinInstanceId;
   373→		CachedGemInstanceId = NewGemInstanceId;
   374→
   375→		// 잔액 갱신
   376→		if (NewCoinBalance != CoinBalance)
   377→		{
   378→			SetBalance(ECurrencyType::Coin, NewCoinBalance);
   379→		}
   380→		if (NewGemBalance != GemBalance)
   381→		{
   382→			SetBalance(ECurrencyType::Gem, NewGemBalance);
   383→		}
   384→
   385→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam 잔액 갱신: Coin=%d (InstanceId=%llu), Gem=%d (InstanceId=%llu)"),
   386→			CoinBalance, CachedCoinInstanceId, GemBalance, CachedGemInstanceId);
   387→		return;
   388→	}
   389→#endif
   390→
   391→	// 비Steam: 로컬 값 유지
   392→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 잔액: Coin=%d, Gem=%d"), CoinBalance, GemBalance);
   393→}
