   600→void UWjWorldCurrencySubsystem::SetBalance(ECurrencyType Type, int32 NewAmount)
   601→{
   602→	NewAmount = FMath::Max(0, NewAmount);
   603→
   604→	switch (Type)
   605→	{
   606→	case ECurrencyType::Coin:
   607→		if (CoinBalance != NewAmount)
   608→		{
   609→			CoinBalance = NewAmount;
   610→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Coin, CoinBalance);
   611→		}
   612→		break;
   613→	case ECurrencyType::Gem:
   614→		if (GemBalance != NewAmount)
   615→		{
   616→			GemBalance = NewAmount;
   617→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Gem, GemBalance);
   618→		}
   619→		break;
   620→	}
   621→}
