   246→void UWjWorldCosmeticSubsystem::PollSteamInventoryResult()
   247→{
   248→#if WITH_STEAM
   249→	if (PendingResultHandle == k_SteamInventoryResultInvalid)
   250→	{
   251→		StopInventoryPolling();
   252→		return;
   253→	}
   254→
   255→	ISteamInventory* SteamInv = SteamInventory();
   256→	if (!SteamInv)
   257→	{
   258→		StopInventoryPolling();
   259→		return;
   260→	}
   261→
   262→	EResult Status = SteamInv->GetResultStatus(PendingResultHandle);
   263→
   264→	if (Status == k_EResultPending)
   265→	{
   266→		// 아직 대기 중 - 계속 폴링
   267→		return;
   268→	}
   269→
   270→	// 결과 처리
   271→	if (Status == k_EResultOK)
   272→	{
   273→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 결과 수신 성공"));
   274→		ParseInventoryResult();
   275→	}
   276→	else
   277→	{
   278→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 결과 실패 (Status: %d)"), static_cast<int32>(Status));
   279→	}
   280→
   281→	// 정리
   282→	SteamInv->DestroyResult(PendingResultHandle);
   283→	PendingResultHandle = k_SteamInventoryResultInvalid;
   284→	StopInventoryPolling();
   285→
   286→	// 델리게이트 브로드캐스트
   287→	OnInventoryUpdated.Broadcast();
   288→#else
   289→	StopInventoryPolling();
   290→#endif
   291→}
