   243→void AWjWorldTreasureChestActor::OnInteract()
   244→{
   245→	if (!bPlayerInRange || !InteractingPlayer)
   246→	{
   247→		return;
   248→	}
   249→
   250→	// 로컬 쿨타임 확인 (UI용, Steam에서는 서버도 이중 검증)
   251→	if (IsOnCooldown())
   252→	{
   253→		UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: On cooldown, remaining: %s"),
   254→			*GetRemainingCooldown().ToString());
   255→		return;
   256→	}
   257→
   258→	// 보상 지급 시도
   259→	if (!TryGrantReward())
   260→	{
   261→		UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Reward grant failed (Steam cooldown or error)"));
   262→		return;
   263→	}
   264→
   265→	// 쿨타임 타임스탬프 저장 (UI 표시용)
   266→	SaveCooldown();
   267→
   268→	// 뚜껑 열기 연출
   269→	PlayLidOpen();
   270→
   271→	// 비주얼 전환
   272→	ApplyCooldownVisual();
   273→
   274→	// UI 갱신
   275→	UpdateInteractionUI();
   276→}
