   355→void AWjWorldTreasureChestActor::UpdateInteractionUI()
   356→{
   357→	if (!InteractionWidget)
   358→	{
   359→		return;
   360→	}
   361→
   362→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   363→	int32 RewardAmount = Settings ? Settings->TreasureChestCoinReward : 50;
   364→
   365→	if (IsOnCooldown())
   366→	{
   367→		FTimespan Remaining = GetRemainingCooldown();
   368→		int32 Hours = static_cast<int32>(Remaining.GetTotalHours());
   369→		int32 Minutes = Remaining.GetMinutes();
   370→		int32 Seconds = Remaining.GetSeconds();
   371→
   372→		FString CooldownText = FString::Printf(TEXT("Next open: %02d:%02d:%02d"), Hours, Minutes, Seconds);
   373→		InteractionWidget->SetInteractionText(CooldownText);
   374→	}
   375→	else
   376→	{
   377→		// 쿨타임 만료 감지 → 타이머 정지 + 비주얼 복원
   378→		GetWorldTimerManager().ClearTimer(CooldownUITimerHandle);
   379→		RemoveCooldownVisual();
   380→		PlayLidClose();
   381→
   382→		FString InteractText = FString::Printf(TEXT("Open Chest (%d Coin)"), RewardAmount);
   383→		InteractionWidget->SetInteractionText(InteractText);
   384→	}
   385→}
