   403→bool AWjWorldTreasureChestActor::IsOnCooldown() const
   404→{
   405→	if (CachedLastOpenedTime.GetTicks() == 0)
   406→	{
   407→		return false;
   408→	}
   409→
   410→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   411→	float CooldownSeconds = Settings ? Settings->TreasureChestCooldownSeconds : 86400.0f;
   412→	return (FDateTime::UtcNow() - CachedLastOpenedTime).GetTotalSeconds() < CooldownSeconds;
   413→}
   414→
   415→FTimespan AWjWorldTreasureChestActor::GetRemainingCooldown() const
   416→{
   417→	if (CachedLastOpenedTime.GetTicks() == 0)
   418→	{
   419→		return FTimespan::Zero();
   420→	}
   421→
   422→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   423→	float CooldownSeconds = Settings ? Settings->TreasureChestCooldownSeconds : 86400.0f;
   424→
   425→	FDateTime CooldownEnd = CachedLastOpenedTime + FTimespan::FromSeconds(CooldownSeconds);
   426→	FTimespan Remaining = CooldownEnd - FDateTime::UtcNow();
   427→
   428→	if (Remaining.GetTotalSeconds() > 0)
   429→	{
   430→		return Remaining;
   431→	}
   432→	return FTimespan::Zero();
   433→}
