   435→void AWjWorldTreasureChestActor::SaveCooldown()
   436→{
   437→	CachedLastOpenedTime = FDateTime::UtcNow();
   438→
   439→	FString Key = GetChestKey();
   440→	FString ConfigPath = GetConfigPath();
   441→
   442→	GConfig->SetString(*ConfigSection, *Key, *CachedLastOpenedTime.ToIso8601(), ConfigPath);
   443→	GConfig->Flush(false, ConfigPath);
   444→
   445→	UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Cooldown saved for %s"), *Key);
   446→}
