   491→
   492→void AWjWorldTreasureChestActor::ApplyCooldownVisual()
   493→{
   494→	if (!MeshComponent)
   495→	{
   496→		return;
   497→	}
   498→
   499→	int32 NumMats = MeshComponent->GetNumMaterials();
   500→	for (int32 i = 0; i < NumMats; ++i)
   501→	{
   502→		UMaterialInstanceDynamic* DMI = MeshComponent->CreateAndSetMaterialInstanceDynamic(i);
   503→		if (DMI)
   504→		{
   505→			// 어두운 회색 틴트
   506→			DMI->SetVectorParameterValue(TEXT("BaseColor"), FLinearColor(0.3f, 0.3f, 0.3f, 1.0f));
   507→			DMI->SetScalarParameterValue(TEXT("Opacity"), 0.5f);
   508→		}
   509→	}
   510→}
