   512→void AWjWorldTreasureChestActor::RemoveCooldownVisual()
   513→{
   514→	// PlacedObjectActor의 원본 머티리얼 복원 패턴과 동일
   515→	// 메시 재로드로 원본 머티리얼 복원
   516→	if (MeshComponent && MeshComponent->GetStaticMesh())
   517→	{
   518→		UStaticMesh* CurrentMesh = MeshComponent->GetStaticMesh();
   519→		int32 NumMats = CurrentMesh->GetStaticMaterials().Num();
   520→		for (int32 i = 0; i < NumMats; ++i)
   521→		{
   522→			MeshComponent->SetMaterial(i, CurrentMesh->GetMaterial(i));
   523→		}
   524→	}
   525→}
