   578→{
   579→	GConfig->SetInt(*CurrencyConfigSection, TEXT("CoinBalance"), CoinBalance, GGameUserSettingsIni);
   580→	GConfig->SetInt(*CurrencyConfigSection, TEXT("GemBalance"), GemBalance, GGameUserSettingsIni);
   581→
   582→	GConfig->Flush(false, GGameUserSettingsIni);
   583→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 잔액 로컬 저장 완료"));
   584→}
