   586→void UWjWorldCurrencySubsystem::LoadBalancesFromLocal()
   587→{
   588→	int32 LoadedCoin = 0;
   589→	int32 LoadedGem = 0;
   590→
   591→	GConfig->GetInt(*CurrencyConfigSection, TEXT("CoinBalance"), LoadedCoin, GGameUserSettingsIni);
   592→	GConfig->GetInt(*CurrencyConfigSection, TEXT("GemBalance"), LoadedGem, GGameUserSettingsIni);
   593→
   594→	CoinBalance = FMath::Max(0, LoadedCoin);
   595→	GemBalance = FMath::Max(0, LoadedGem);
   596→
   597→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 잔액 로컬 로드 완료 (Coin: %d, Gem: %d)"), CoinBalance, GemBalance);
   598→}
   599→
   600→void UWjWorldCurrencySubsystem::SetBalance(ECurrencyType Type, int32 NewAmount)
   601→{
   602→	NewAmount = FMath::Max(0, NewAmount);
   603→
   604→	switch (Type)
   605→	{
   606→	case ECurrencyType::Coin:
   607→		if (CoinBalance != NewAmount)
   608→		{
   609→			CoinBalance = NewAmount;
   610→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Coin, CoinBalance);
   611→		}
   612→		break;
   613→	case ECurrencyType::Gem:
   614→		if (GemBalance != NewAmount)
   615→		{
   616→			GemBalance = NewAmount;
   617→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Gem, GemBalance);
   618→		}
   619→		break;
   620→	}
   621→}
