   101→void AWjWorldTreasureChestActor::EndPlay(const EEndPlayReason::Type EndPlayReason)
   102→{
   103→	// 입력 해제 + 바인딩 정리
   104→	if (InteractingPlayer)
   105→	{
   106→		APlayerController* PC = Cast<APlayerController>(InteractingPlayer->GetController());
   107→		if (PC)
   108→		{
   109→			DisableInput(PC);
   110→		}
   111→	}
   112→	if (InputComponent)
   113→	{
   114→		InputComponent->ClearActionBindings();
   115→	}
   116→	bInputBound = false;
   117→
   118→	// 쿨타임 UI 타이머 정리
   119→	GetWorldTimerManager().ClearTimer(CooldownUITimerHandle);
   120→
   121→	Super::EndPlay(EndPlayReason);
   122→}
