   124→void AWjWorldTreasureChestActor::Tick(float DeltaTime)
   125→{
   126→	Super::Tick(DeltaTime);
   127→
   128→	if (!bLidAnimating || !LidMeshComponent)
   129→	{
   130→		SetActorTickEnabled(false);
   131→		bLidAnimating = false;
   132→		return;
   133→	}
   134→
   135→	float TargetRoll = bLidOpening ? LidOpenedRoll : LidClosedRoll;
   136→	float Direction = (TargetRoll > LidCurrentRoll) ? 1.0f : -1.0f;
   137→	LidCurrentRoll += Direction * LidAnimSpeed * DeltaTime;
   138→
   139→	// 목표 도달 확인
   140→	bool bReached = (Direction > 0.0f)
   141→		? (LidCurrentRoll >= TargetRoll)
   142→		: (LidCurrentRoll <= TargetRoll);
   143→
   144→	if (bReached)
   145→	{
   146→		LidCurrentRoll = TargetRoll;
   147→		bLidAnimating = false;
   148→		SetActorTickEnabled(false);
   149→	}
   150→
   151→	FRotator LidRot = LidMeshComponent->GetRelativeRotation();
   152→	LidRot.Roll = LidCurrentRoll;
   153→	LidMeshComponent->SetRelativeRotation(LidRot);
   154→}
