   156→void AWjWorldTreasureChestActor::OnTriggerBeginOverlap(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor,
   157→	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex, bool bFromSweep, const FHitResult& SweepResult)
   158→{
   159→	APawn* Pawn = Cast<APawn>(OtherActor);
   160→	if (!Pawn || !Pawn->IsPlayerControlled())
   161→	{
   162→		return;
   163→	}
   164→
   165→	bPlayerInRange = true;
   166→	InteractingPlayer = Pawn;
   167→
   168→	// 입력 바인딩 (중복 방지)
   169→	APlayerController* PC = Cast<APlayerController>(Pawn->GetController());
   170→	if (PC)
   171→	{
   172→		EnableInput(PC);
   173→
   174→		if (!bInputBound)
   175→		{
   176→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   177→			if (Settings && InputComponent)
   178→			{
   179→				UInputAction* IA = Settings->TreasureChestInteractAction.LoadSynchronous();
   180→				if (IA)
   181→				{
   182→					if (UEnhancedInputComponent* EIC = Cast<UEnhancedInputComponent>(InputComponent))
   183→					{
   184→						EIC->BindAction(IA, ETriggerEvent::Started, this, &AWjWorldTreasureChestActor::OnInteract);
   185→						bInputBound = true;
   186→					}
   187→				}
   188→			}
   189→		}
   190→	}
   191→
   192→	// 쿨타임 만료 시 비주얼 복원 (Fix 3)
   193→	if (!IsOnCooldown())
   194→	{
   195→		RemoveCooldownVisual();
   196→		PlayLidClose();
   197→	}
   198→
   199→	ShowInteractionUI();
   200→
   201→	// 쿨타임 중이면 UI 실시간 갱신 타이머 시작 (Fix 4)
   202→	if (IsOnCooldown())
   203→	{
   204→		GetWorldTimerManager().SetTimer(CooldownUITimerHandle, this,
   205→			&AWjWorldTreasureChestActor::UpdateInteractionUI, 1.0f, true);
   206→	}
   207→
   208→	UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Player entered range"));
   209→}
