   211→void AWjWorldTreasureChestActor::OnTriggerEndOverlap(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor,
   212→	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex)
   213→{
   214→	APawn* Pawn = Cast<APawn>(OtherActor);
   215→	if (!Pawn || !Pawn->IsPlayerControlled())
   216→	{
   217→		return;
   218→	}
   219→
   220→	// 입력 해제 + 바인딩 정리
   221→	APlayerController* PC = Cast<APlayerController>(Pawn->GetController());
   222→	if (PC)
   223→	{
   224→		DisableInput(PC);
   225→	}
   226→	if (InputComponent)
   227→	{
   228→		InputComponent->ClearActionBindings();
   229→	}
   230→	bInputBound = false;
   231→
   232→	// 쿨타임 UI 타이머 정리
   233→	GetWorldTimerManager().ClearTimer(CooldownUITimerHandle);
   234→
   235→	bPlayerInRange = false;
   236→	InteractingPlayer = nullptr;
   237→
   238→	HideInteractionUI();
   239→
   240→	UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Player left range"));
   241→}
   242→
   243→void AWjWorldTreasureChestActor::OnInteract()
   244→{
   245→	if (!bPlayerInRange || !InteractingPlayer)
   246→	{
   247→		return;
   248→	}
   249→
   250→	// 로컬 쿨타임 확인 (UI용, Steam에서는 서버도 이중 검증)
   251→	if (IsOnCooldown())
   252→	{
   253→		UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: On cooldown, remaining: %s"),
   254→			*GetRemainingCooldown().ToString());
   255→		return;
   256→	}
   257→
   258→	// 보상 지급 시도
   259→	if (!TryGrantReward())
   260→	{
   261→		UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Reward grant failed (Steam cooldown or error)"));
   262→		return;
   263→	}
   264→
   265→	// 쿨타임 타임스탬프 저장 (UI 표시용)
   266→	SaveCooldown();
   267→
   268→	// 뚜껑 열기 연출
   269→	PlayLidOpen();
   270→
   271→	// 비주얼 전환
   272→	ApplyCooldownVisual();
   273→
   274→	// UI 갱신
   275→	UpdateInteractionUI();
   276→}
   277→
   278→bool AWjWorldTreasureChestActor::TryGrantReward()
   279→{
   280→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   281→	if (!Settings)
   282→	{
   283→		return false;
   284→	}
   285→
   286→#if WITH_STEAM
   287→	ISteamInventory* SteamInv = SteamInventory();
   288→	if (SteamInv)
   289→	{
   290→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   291→		int32 GeneratorDefId = Settings->TreasureChestGeneratorStartDefId + ChestIndex;
   292→		SteamItemDef_t DropDef = static_cast<SteamItemDef_t>(GeneratorDefId);
   293→
   294→		if (SteamInv->TriggerItemDrop(&ResultHandle, DropDef))
   295→		{
   296→			UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 요청 성공 (DefId: %d)"),
   297→				ChestIndex, GeneratorDefId);
   298→			SteamInv->DestroyResult(ResultHandle);
   299→
   300→			// 인벤토리 갱신으로 잔액 반영
   301→			UGameInstance* GI = GetGameInstance();
   302→			if (GI)
   303→			{
   304→				UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   305→				if (CosmeticSub)
   306→				{
   307→					CosmeticSub->RequestInventoryRefresh();
   308→				}
   309→			}
   310→
   311→			return true;
   312→		}
   313→		else
   314→		{
   315→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 호출 실패 (DefId: %d)"),
   316→				ChestIndex, GeneratorDefId);
   317→			return false;
   318→		}
   319→	}
   320→#endif
   321→
   322→	// 비Steam 폴백: 로컬 재화 부여
   323→	int32 RewardAmount = Settings->TreasureChestCoinReward;
   324→	UGameInstance* GI = GetGameInstance();
   325→	if (GI)
   326→	{
   327→		UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   328→		if (CurrencySub)
   329→		{
   330→			CurrencySub->GrantCurrencyLocally(ECurrencyType::Coin, RewardAmount);
   331→			UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest: 로컬 보상 %d Coin 지급"), RewardAmount);
   332→		}
   333→	}
   334→
   335→	return true;
   336→}
