   338→void AWjWorldTreasureChestActor::ShowInteractionUI()
   339→{
   340→	if (InteractionWidgetComponent)
   341→	{
   342→		InteractionWidgetComponent->SetVisibility(true);
   343→		UpdateInteractionUI();
   344→	}
   345→}
   346→
   347→void AWjWorldTreasureChestActor::HideInteractionUI()
   348→{
   349→	if (InteractionWidgetComponent)
   350→	{
   351→		InteractionWidgetComponent->SetVisibility(false);
   352→	}
