   389→FString AWjWorldTreasureChestActor::GetChestKey() const
   390→{
   391→	FVector Loc = GetActorLocation();
   392→	return FString::Printf(TEXT("Chest_%d_%d_%d"),
   393→		FMath::RoundToInt(Loc.X),
   394→		FMath::RoundToInt(Loc.Y),
   395→		FMath::RoundToInt(Loc.Z));
   396→}
