   449→
   450→void AWjWorldTreasureChestActor::PlayLidOpen()
   451→{
   452→	bLidOpening = true;
   453→	bLidAnimating = true;
   454→	SetActorTickEnabled(true);
   455→}
   456→
   457→void AWjWorldTreasureChestActor::PlayLidClose()
   458→{
   459→	bLidOpening = false;
   460→	bLidAnimating = true;
   461→	SetActorTickEnabled(true);
   462→}
   463→
   464→void AWjWorldTreasureChestActor::SetLidOpenImmediate()
   465→{
   466→	LidCurrentRoll = LidOpenedRoll;
   467→	bLidAnimating = false;
   468→
   469→	if (LidMeshComponent)
   470→	{
   471→		FRotator LidRot = LidMeshComponent->GetRelativeRotation();
   472→		LidRot.Roll = LidOpenedRoll;
   473→		LidMeshComponent->SetRelativeRotation(LidRot);
   474→	}
   475→}
   476→
   477→void AWjWorldTreasureChestActor::SetLidCloseImmediate()
   478→{
   479→	LidCurrentRoll = LidClosedRoll;
   480→	bLidAnimating = false;
   481→
   482→	if (LidMeshComponent)
   483→	{
   484→		FRotator LidRot = LidMeshComponent->GetRelativeRotation();
   485→		LidRot.Roll = LidClosedRoll;
   486→		LidMeshComponent->SetRelativeRotation(LidRot);
   487→	}
   488→}
   489→
   490→// === Visual ===
   491→
   492→void AWjWorldTreasureChestActor::ApplyCooldownVisual()
   493→{
   494→	if (!MeshComponent)
   495→	{
   496→		return;
   497→	}
   498→
   499→	int32 NumMats = MeshComponent->GetNumMaterials();
   500→	for (int32 i = 0; i < NumMats; ++i)
   501→	{
   502→		UMaterialInstanceDynamic* DMI = MeshComponent->CreateAndSetMaterialInstanceDynamic(i);
   503→		if (DMI)
   504→		{
   505→			// 어두운 회색 틴트
   506→			DMI->SetVectorParameterValue(TEXT("BaseColor"), FLinearColor(0.3f, 0.3f, 0.3f, 1.0f));
   507→			DMI->SetScalarParameterValue(TEXT("Opacity"), 0.5f);
   508→		}
   509→	}
   510→}
   511→
   512→void AWjWorldTreasureChestActor::RemoveCooldownVisual()
   513→{
   514→	// PlacedObjectActor의 원본 머티리얼 복원 패턴과 동일
   515→	// 메시 재로드로 원본 머티리얼 복원
   516→	if (MeshComponent && MeshComponent->GetStaticMesh())
   517→	{
   518→		UStaticMesh* CurrentMesh = MeshComponent->GetStaticMesh();
   519→		int32 NumMats = CurrentMesh->GetStaticMaterials().Num();
   520→		for (int32 i = 0; i < NumMats; ++i)
   521→		{
   522→			MeshComponent->SetMaterial(i, CurrentMesh->GetMaterial(i));
   523→		}
   524→	}
   525→}
