+void AWjWorldTreasureChestActor::ResetCooldown()
+{
+	CachedLastOpenedTime = FDateTime();
+
+	// GConfig에서도 제거
+	FString Key = GetChestKey();
+	FString ConfigPath = GetConfigPath();
+	GConfig->RemoveKey(*ConfigSection, *Key, ConfigPath);
