   555→void UWjWorldCurrencySubsystem::PollExchangeResult()
   556→{
   557→#if WITH_STEAM
   558→	if (!bExchangePending || ExchangeResultHandle == k_SteamInventoryResultInvalid)
   559→	{
   560→		StopExchangePolling();
   561→		return;
   562→	}
   563→
   564→	ISteamInventory* SteamInv = SteamInventory();
   565→	if (!SteamInv)
   566→	{
   567→		StopExchangePolling();
   568→		bExchangePending = false;
   569→		OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   570→		PendingExchangeItemId = NAME_None;
   571→		return;
   572→	}
   573→
   574→	EResult Status = SteamInv->GetResultStatus(ExchangeResultHandle);
   575→	if (Status == k_EResultPending)
   576→	{
   577→		return;
   578→	}
   579→
   580→	bool bSuccess = (Status == k_EResultOK);
   581→	if (bSuccess)
   582→	{
   583→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Exchange 성공: %s"), *PendingExchangeItemId.ToString());
   584→
   585→		// 인벤토리 갱신
   586→		UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   587→		if (CosmeticSub)
   588→		{
   589→			CosmeticSub->RequestInventoryRefresh();
   590→		}
   591→	}
   592→	else
   593→	{
   594→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Exchange 실패: %s (Status: %d)"),
   595→			*PendingExchangeItemId.ToString(), static_cast<int32>(Status));
   596→	}
   597→
   598→	SteamInv->DestroyResult(ExchangeResultHandle);
   599→	ExchangeResultHandle = k_SteamInventoryResultInvalid;
   600→
   601→	bExchangePending = false;
   602→	OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   603→	PendingExchangeItemId = NAME_None;
   604→
   605→	StopExchangePolling();
   606→#else
   607→	StopExchangePolling();
   608→#endif
   609→}
