   675→{
   676→	UWorld* World = GetWorld();
   677→	if (!World)
   678→	{
   679→		return;
   680→	}
   681→
   682→	World->GetTimerManager().SetTimer(
   683→		GemPurchasePollTimerHandle,
   684→		this,
   685→		&UWjWorldCurrencySubsystem::PollGemPurchaseResult,
   686→		1.0f,
   687→		true
   688→	);
   689→}
