   726→
   727→	switch (Type)
   728→	{
   729→	case ECurrencyType::Coin:
   730→		if (CoinBalance != NewAmount)
   731→		{
   732→			CoinBalance = NewAmount;
   733→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Coin, CoinBalance);
   734→		}
   735→		break;
   736→	case ECurrencyType::Gem:
   737→		if (GemBalance != NewAmount)
   738→		{
   739→			GemBalance = NewAmount;
   740→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Gem, GemBalance);
   741→		}
   742→		break;
   743→	}
   744→}
