    29→void UWjWorldPlacementComponent::EnterPlacementMode()
    30→{
    31→	// 기본 컨텍스트: Lobby
    32→	EnterPlacementModeWithContext(EPlacementContext::Lobby);
    33→}
    34→
    35→void UWjWorldPlacementComponent::EnterPlacementModeWithContext(EPlacementContext Context)
    36→{
    37→	if (CurrentMode != EPlacementMode::None)
    38→	{
    39→		return;
    40→	}
    41→
    42→	CurrentContext = Context;
    43→
    44→	// DeveloperSettings에서 입력 설정 및 Catalog 로드 (컨텍스트별)
    45→	LoadInputSettings();
    46→	EnsureCatalogLoaded();
    47→
    48→	CurrentMode = EPlacementMode::Placing;
    49→	SetComponentTickEnabled(true);
    50→	BindInputActions();
    51→	RefreshPlacementModeVisuals();
    52→
    53→	OnPlacementModeChanged.Broadcast(CurrentMode);
    54→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Entered placement mode (Context: %s)"),
    55→		*GetPlacementContextName(CurrentContext));
    56→}
    57→
    58→void UWjWorldPlacementComponent::ExitPlacementMode()
    59→{
    60→	if (CurrentMode == EPlacementMode::None)
    61→	{
    62→		return;
    63→	}
    64→
    65→	// 호버 하이라이트 해제
    66→	if (HoveredObject)
    67→	{
    68→		HoveredObject->SetHighlighted(false);
    69→		HoveredObject = nullptr;
    70→	}
    71→
    72→	DestroyPreview();
    73→	UnbindInputActions();
    74→	SetComponentTickEnabled(false);
    75→
    76→	SelectedObjectId = NAME_None;
    77→	CurrentMode = EPlacementMode::None;
    78→	bAirPlacementMode = false;
    79→	AirPlaneHeight = 0.f;
    80→	// 컨텍스트는 리셋하지 않음 (다음 EnterPlacementMode 시 설정)
    81→
    82→	RefreshPlacementModeVisuals();
    83→
    84→	OnPlacementModeChanged.Broadcast(CurrentMode);
    85→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Exited placement mode"));
    86→}
    87→
    88→void UWjWorldPlacementComponent::ToggleDeleteMode()
    89→{
    90→	if (CurrentMode == EPlacementMode::None)
    91→	{
    92→		return;
    93→	}
    94→
    95→	if (CurrentMode == EPlacementMode::Deleting)
    96→	{
    97→		// 삭제 모드 해제 → 배치 모드 복귀
    98→		if (HoveredObject)
    99→		{
   100→			HoveredObject->SetHighlighted(false);
   101→			HoveredObject = nullptr;
   102→		}
   103→		CurrentMode = EPlacementMode::Placing;
   104→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Switched to placing mode"));
   105→	}
   106→	else
   107→	{
   108→		// 배치 모드 → 삭제 모드
   109→		DestroyPreview();
   110→		CurrentMode = EPlacementMode::Deleting;
   111→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Switched to delete mode"));
   112→	}
   113→
   114→	OnPlacementModeChanged.Broadcast(CurrentMode);
   115→}
